import 'package:flutter/material.dart'; class SettingSlider extends StatelessWidget{const SettingSlider({super.key,required this.value,required this.label,required this.onChanged});final double value;final String label;final ValueChanged<double> onChanged;@override Widget build(BuildContext c)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label,style:Theme.of(c).textTheme.titleMedium),Slider(value:value,min:500,max:2000,divisions:15,label:value.round().toString()+' ms',onChanged:onChanged)]);}